{
  "pou_name": "MotorControl",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "VAR_INPUT
  StartBtn : BOOL;
  StopBtn : BOOL;
  EStop : BOOL;
END_VAR

VAR_OUTPUT
  Motor : BOOL;
END_VAR",
  "implementation": "IF EStop THEN
  Motor := FALSE;
ELSIF StopBtn THEN
  Motor := FALSE;
ELSIF StartBtn THEN
  Motor := TRUE;
ELSE
  (* 保持当前状态 *)
END_IF;"
}
